public class PaymentReference {

    public static PaymentReference emptyReference() {
        return new PaymentReference("");
    }

    public PaymentReference(String reference) {
        this.reference = reference;
    }

    public static PaymentReference of(String reference) {
        return new PaymentReference(reference);
    }

    private static final int maxLength = 18;
    private static final char[] validSymbols = {' ', '-', '.'}; //must be in order for binary search
    private static final String[] nationwideProhibitedWords = {"echo", "delete", "config", "exec", "system", "shell_exec", "passthru"};


    public String getReference() {
        return reference;
    }

    private final String reference;

    @Override
    public boolean equals(Object obj) {
        if (obj instanceof PaymentReference){
            return this.reference.equals(((PaymentReference)obj).reference);
        }
        return false;
    }
}